- How would you adapt for a larger rating scale (e.g., 1–1000)?
- How would you support sliding-window mode across the last K batches?

## Why This Is Asked
This question tests practical amortized analysis for dynamic frequency tracking, demonstrates how to monitor hot keys efficiently, and contrasts incremental updates with full recomputation.

## Key Concepts
- Amortized analysis for batched updates
- Frequency buckets for O(1) max-frequency queries
- Hash maps for per-label counts
- Sparse vs. dense label domains
- Space-time tradeoff analysis

## Code Example
```javascript
class HotKeyTracker {
  constructor(initialCounts) {
    this.cnt = new Map();
    this.freq = new Map();
    this.maxFreq = 0;
    for (const [k, v] of Object.entries(initialCounts)) {
      this.cnt.set(k, v);
      this.freq.set(v, (this.freq.get(v) || 0) + 1);
      this.maxFreq = Math.max(this.maxFreq, v);
    }
  }

  update(label, delta) {
    const old = this.cnt.get(label) || 0;
    const freqCount = this.freq.get(old) || 0;
    if (freqCount === 1) this.freq.delete(old);
    else this.freq.set(old, freqCount - 1);

    const nw = old + delta;
    this.cnt.set(label, nw);
    this.freq.set(nw, (this.freq.get(nw) || 0) + 1);
    this.maxFreq = Math.max(this.maxFreq, nw);
  }

  hasHotKey(threshold) {
    return this.maxFreq >= threshold;
  }
}
```

## Why This Is Asked
This tests basic algorithmic analysis and trade-offs between brute force and divide-and-conquer techniques.

## Key Concepts
- Time complexity and space usage
- Inversions problem and two standard approaches
- Trade-offs with input size and data order

## Code Example
```javascript
function countInversionsNaive(a){
  let c=0;
  for(let i=0;i<a.length;i++){
    for(let j=i+1;j<a.length;j++){
      if(a[i]>a[j]) c++;
    }
  }
  return c;
}
function countInversionsMergeSort(a){
  function sortCount(arr){
    if(arr.length<=1) return {array: arr, inv:0};
    const mid = Math.floor(arr.length/2);
    const left = sortCount(arr.slice(0,mid));
    const right = sortCount(arr.slice(mid));
    let i=0,j=0, merged=[], inv= left.inv + right.inv;
    while(i<left.array.length && j<right.array.length){
      if(left.array[i] <= right.array[j]) merged.push(left.array[i++]);
      else { merged.push(right.array[j++]); inv += left.array.length - i; }
    }
    return {array: merged.concat(left.array.slice(i)).concat(right.array.slice(j)), inv: inv};
  }
  return sortCount(a).inv;
}
```

